import { useId } from "react";

import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { RiAppleLine, RiBankCardLine, RiPaypalLine } from "@remixicon/react";

export default function Component() {
	const id = useId();
	return (
		<RadioGroup className="grid-cols-3" defaultValue="1">
			{/* Credit card */}
			<div className="border-input has-data-[state=checked]:border-primary/50 has-focus-visible:border-ring has-focus-visible:ring-ring/50 relative flex cursor-pointer flex-col items-center gap-3 rounded-md border px-2 py-3 text-center shadow-2xs transition-[color,box-shadow] outline-hidden has-focus-visible:ring-[3px]">
				<RadioGroupItem id={`${id}-1`} value="1" className="sr-only" />
				<RiBankCardLine
					className="opacity-60"
					size={20}
					aria-hidden="true"
				/>
				<label
					htmlFor={`${id}-1`}
					className="text-foreground cursor-pointer text-xs leading-none font-medium after:absolute after:inset-0"
				>
					Card
				</label>
			</div>
			{/* PayPal */}
			<div className="border-input has-data-[state=checked]:border-primary/50 has-focus-visible:border-ring has-focus-visible:ring-ring/50 relative flex cursor-pointer flex-col items-center gap-3 rounded-md border px-2 py-3 text-center shadow-2xs transition-[color,box-shadow] outline-hidden has-focus-visible:ring-[3px]">
				<RadioGroupItem id={`${id}-2`} value="2" className="sr-only" />
				<RiPaypalLine className="opacity-60" size={20} aria-hidden="true" />
				<label
					htmlFor={`${id}-2`}
					className="text-foreground cursor-pointer text-xs leading-none font-medium after:absolute after:inset-0"
				>
					PayPal
				</label>
			</div>
			{/* Apple Pay */}
			<div className="border-input has-data-[state=checked]:border-primary/50 has-focus-visible:border-ring has-focus-visible:ring-ring/50 relative flex cursor-pointer flex-col items-center gap-3 rounded-md border px-2 py-3 text-center shadow-2xs transition-[color,box-shadow] outline-hidden has-focus-visible:ring-[3px]">
				<RadioGroupItem id={`${id}-3`} value="3" className="sr-only" />
				<RiAppleLine className="opacity-60" size={20} aria-hidden="true" />
				<label
					htmlFor={`${id}-3`}
					className="text-foreground cursor-pointer text-xs leading-none font-medium after:absolute after:inset-0"
				>
					Apple Pay
				</label>
			</div>
		</RadioGroup>
	);
}

"use client";

import React from "react";

import { cn } from "@/lib/utils";
import * as RadioGroupPrimitive from "@radix-ui/react-radio-group";
import { Circle } from "lucide-react";

const RadioGroup = React.forwardRef<
	React.ElementRef<typeof RadioGroupPrimitive.Root>,
	React.ComponentPropsWithoutRef<typeof RadioGroupPrimitive.Root>
>(({ className, ...props }, ref) => {
	return (
		<RadioGroupPrimitive.Root
			className={cn("grid gap-2", className)}
			{...props}
			ref={ref}
		/>
	);
});
RadioGroup.displayName = RadioGroupPrimitive.Root.displayName;

const RadioGroupItem = React.forwardRef<
	React.ElementRef<typeof RadioGroupPrimitive.Item>,
	React.ComponentPropsWithoutRef<typeof RadioGroupPrimitive.Item>
>(({ className, ...props }, ref) => {
	return (
		<RadioGroupPrimitive.Item
			ref={ref}
			className={cn(
				"aspect-square h-4 w-4 rounded-full border border-primary text-primary ring-offset-background focus:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50",
				className
			)}
			{...props}
		>
			<RadioGroupPrimitive.Indicator className="flex items-center justify-center">
				<Circle className="h-2.5 w-2.5 fill-current text-current" />
			</RadioGroupPrimitive.Indicator>
		</RadioGroupPrimitive.Item>
	);
});
RadioGroupItem.displayName = RadioGroupPrimitive.Item.displayName;

export { RadioGroup, RadioGroupItem };
